108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        HttpHeaders headers = new HttpHeaders();
112	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
113	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
114	        owner.setTelephone(normalizedTelephone);
115	        owner.setEmail(normalizeEmail(owner.getEmail()));
116	        owner.setAddress(normalizeAddress(owner.getAddress()));
117	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
118	        if (effectiveRegistrationDate == null) {
119	            effectiveRegistrationDate = LocalDate.now();
120	        }
121	        effectiveRegistrationDate = rollToBusinessDay(effectiveRegistrationDate);
122	        owner.setRegistrationDate(effectiveRegistrationDate);
123	        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= DAILY_CREATE_LIMIT) {
124	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
125	                "the maximum number of owners that may be created today has been reached");
126	        }
127	        if (isTelephoneInUse(normalizedTelephone, null)) {
128	            throw new ResponseStatusException(HttpStatus.CONFLICT,
129	                "telephone is already in use by another owner");
130	        }
131	        if (isEmailInUse(owner.getEmail(), null)) {
132	            throw new ResponseStatusException(HttpStatus.CONFLICT,
133	                "email is already in use by another owner");
134	        }
135	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
136	        if (!sharesHousehold
137	            && this.clinicService.isHouseholdInUse(owner.getLastName(), owner.getAddress(), null)) {
138	            throw new ResponseStatusException(HttpStatus.CONFLICT,
139	                "another owner with the same last name already lives at this address");
140	        }
141	        if (countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
142	            throw new ResponseStatusException(HttpStatus.CONFLICT,
143	                "city has reached its maximum number of owners");
144	        }
145	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
146	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
147	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
148	        owner.setBulkSignupWarning(
149	            countOwnersRegisteredOn(effectiveRegistrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
150	        if (sharesHousehold) {
151	            this.clinicService.assignHousehold(owner);
152	        }
153	        this.clinicService.saveOwner(owner);
154	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
155	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
156	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
157	            ownerDto.getMembershipLevel());
158	        headers.setLocation(UriComponentsBuilder.newInstance()
159	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
160	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Override
165	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
166	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
167	        if (currentOwner == null) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        currentOwner.setAddress(ownerFieldsDto.getAddress());
171	        currentOwner.setCity(ownerFieldsDto.getCity());
172	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
173	        currentOwner.setLastName(ownerFieldsDto.getLastName());
174	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
175	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
176	        this.clinicService.saveOwner(currentOwner);
177	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
178	    }
179	
180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Transactional
182	    @Override
183	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
184	        Owner owner = this.clinicService.findOwnerById(ownerId);
185	        if (owner == null) {
186	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
187	        }
188	        this.clinicService.deleteOwner(owner);
189	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
190	    }
