242	
243	
244	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
245	    @Override
246	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
247	        Owner owner = this.clinicService.findOwnerById(ownerId);
248	        if (owner != null) {
249	            Pet pet = owner.getPet(petId);
250	            if (pet != null) {
251	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
252	            }
253	        }
254	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
255	    }
256	
257	    /**
258	     * Builds the customer code for a new owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is
259	     * the upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
260	     * last name, and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
261	     * owners that already live in that city (e.g. {@code 'LON-SMI-0007'}).
262	     *
263	     * @param city     the owner's city
264	     * @param lastName the owner's last name
265	     * @return the assigned customer code
266	     */
267	    private String nextCustomerCode(String city, String lastName) {
268	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
269	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
270	        int sequence = countOwnersInCity(city) + 1;
271	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
272	    }
273	
274	    /**
275	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
276	     * owner's city already contains this many owners.
277	     */
278	    private static final int CITY_CAPACITY = 50;
279	
280	    /**
281	     * The maximum number of owners that may be created on a single day. A create is rejected with
282	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
283	     * {@code registrationDate}.
284	     */
285	    private static final int DAILY_CREATE_LIMIT = 100;
286	
287	    /**
288	     * The number of owners that must already have been created for the current day before a new
289	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
290	     * owners already carry today's {@code registrationDate}.
291	     */
292	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
293	
294	    /**
295	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday or
296	     * Sunday is moved forward to the following Monday, while a date already on a weekday is returned
297	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
298	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
299	     * falls on a business day.
300	     *
301	     * @param date the effective registration date
302	     * @return the same date when it is a weekday, otherwise the following Monday
303	     */
304	    private static LocalDate rollToBusinessDay(LocalDate date) {
305	        return switch (date.getDayOfWeek()) {
306	            case SATURDAY -> date.plusDays(2);
307	            case SUNDAY -> date.plusDays(1);
308	            default -> date;
309	        };
310	    }
311	
312	    /**
313	     * Counts the existing owners whose {@code registrationDate} equals the given (already
314	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
315	     * business day. Called before a new owner is saved, so the returned value reflects the number of
316	     * owners created for that day prior to this create.
317	     *
318	     * @param date the adjusted business-day registration date to count against
319	     * @return the number of existing owners registered on that date
320	     */
321	    private int countOwnersRegisteredOn(LocalDate date) {
322	        return (int) this.clinicService.findAllOwners().stream()
323	            .filter(existing -> date.equals(existing.getRegistrationDate()))
324	            .count();
325	    }
326	
327	    /**
328	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
329	     *
330	     * @param city the city to count owners for
331	     * @return the number of existing owners in that city
332	     */
333	    private int countOwnersInCity(String city) {
334	        return (int) this.clinicService.findAllOwners().stream()
335	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
336	            .count();
337	    }
338	
339	    /**
340	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
341	     * the last two digits of the registration date's year (e.g. {@code 'LON-SMI-0007-M26'}).
342	     *
343	     * @param customerCode     the owner's assigned customer code
344	     * @param registrationDate the owner's registration date
345	     * @return the assigned membership number
346	     */
347	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
348	        String yy = String.format("%02d", registrationDate.getYear() % 100);
349	        return String.format("%s-M%s", customerCode, yy);
350	    }
351	
352	    /**
353	     * Counts the existing owners that already share the given first name and last name, comparing
354	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
355	     * the number of namesakes that existed prior to this create.
356	     *
357	     * @param firstName the new owner's first name
358	     * @param lastName  the new owner's last name
359	     * @return the number of existing owners with the same first and last name
360	     */
361	    private int countNamesakes(String firstName, String lastName) {
362	        int count = 0;
363	        for (Owner existing : this.clinicService.findAllOwners()) {
364	            if (firstName.equalsIgnoreCase(existing.getFirstName())
365	                && lastName.equalsIgnoreCase(existing.getLastName())) {
366	                count++;
367	            }
368	        }
369	        return count;
370	    }
371	
372	    /**
373	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
374	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
375	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
376	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
377	     * string is what gets stored and returned.
378	     *
379	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
380	     *
381	     * @param telephone the raw telephone value supplied by the client
382	     * @return the normalized E.164 telephone number
383	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
384	     *                                 valid E.164 number (unexpected characters, or not 8 to 15
385	     *                                 digits after the {@code '+'})
386	     */
387	    private static String normalizeTelephone(String telephone) {
388	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
389	        String digits;
390	        if (cleaned.startsWith("+")) {
391	            digits = cleaned.substring(1);
392	        } else {
393	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
394	            digits = "61" + national;
395	        }
396	        if (!digits.matches("[0-9]{8,15}")) {
397	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
398	                "telephone could not be normalized to a valid E.164 number");
399	        }
400	        return "+" + digits;
401	    }
402	
403	    /**
404	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, falling back
405	     * to the raw stored value if it cannot be normalized (e.g. legacy seed data in another format).
406	     *
407	     * @param telephone the stored telephone value, possibly {@code null}
408	     * @return the E.164 form, or the raw value when it cannot be normalized
409	     */
410	    private static String toComparableTelephone(String telephone) {
411	        try {
412	            return normalizeTelephone(telephone);
413	        } catch (ResponseStatusException ex) {
414	            return telephone;
415	        }
416	    }
417	
418	    /**
419	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
420	     * containing at least one dot, none of the three sections containing whitespace or an
421	     * additional {@code @}.
422	     */
423	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
424	
425	    /**
426	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
427	     * (email is optional). When a value is supplied it must be a syntactically valid address; the
428	     * value is then stored and returned lower-cased.
429	     *
430	     * @param email the raw email value supplied by the client, possibly {@code null}
431	     * @return the lower-cased email, or {@code null} when none was supplied
432	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
433	     *                                 is not a syntactically valid address
434	     */
435	    private static String normalizeEmail(String email) {
436	        if (email == null) {
437	            return null;
438	        }
439	        if (!EMAIL_PATTERN.matcher(email).matches()) {
440	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
441	                "email must be a syntactically valid address");
442	        }
443	        return email.toLowerCase(Locale.ROOT);
444	    }
445	
446	    /**
447	     * Common street-type abbreviations expanded to their full word during address normalization.
448	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
449	     */
450	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
451	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
452	
453	    /**
454	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
455	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
456	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
457	     * {@code AVE -> AVENUE}). This normalized value is what gets stored, returned, and used for every
458	     * address comparison (household duplicate detection and the shared household id).
459	     *
460	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
461	     *
462	     * @param address the raw address supplied by the client, possibly {@code null}
463	     * @return the normalized address
464	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
465	     *                                 after normalization (required field)
466	     */
467	    private static String normalizeAddress(String address) {
468	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
469	        if (collapsed.isEmpty()) {
470	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
471	                "address must not be blank");
472	        }
473	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
474	        StringBuilder normalized = new StringBuilder();
475	        for (int i = 0; i < tokens.length; i++) {
476	            if (i > 0) {
477	                normalized.append(' ');
478	            }
479	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
480	        }
481	        return normalized.toString();
482	    }
483	
484	    /**
485	     * Determines whether the given normalized E.164 telephone is already used by any owner other
486	     * than the one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g.
487	     * on create). Stored telephones are compared by their E.164 value so that differently formatted
488	     * inputs representing the same number are treated as duplicates.
489	     *
490	     * @param normalizedTelephone the already-normalized E.164 telephone to look for
491	     * @param excludeId           id of an owner to ignore during the check, or {@code null} for none
492	     * @return {@code true} if another owner already uses the telephone
493	     */
494	    private boolean isTelephoneInUse(String normalizedTelephone, Integer excludeId) {
495	        for (Owner existing : this.clinicService.findAllOwners()) {
496	            if (excludeId != null && excludeId.equals(existing.getId())) {
497	                continue;
498	            }
499	            if (normalizedTelephone.equals(toComparableTelephone(existing.getTelephone()))) {
500	                return true;
501	            }
502	        }
503	        return false;
504	    }
505	
506	    /**
507	     * Determines whether the given (already normalized, lower-cased) email is already used by any
508	     * owner other than the one identified by {@code excludeId} (pass {@code null} to consider every
509	     * owner, e.g. on create). Stored emails are compared case-insensitively, so two addresses that
510	     * differ only in letter case are treated as duplicates. A {@code null} email never matches, as
511	     * email is optional.
512	     *
513	     * @param normalizedEmail the already-normalized lower-cased email to look for, or {@code null}
514	     * @param excludeId       id of an owner to ignore during the check, or {@code null} for none
515	     * @return {@code true} if another owner already uses the email
516	     */
517	    private boolean isEmailInUse(String normalizedEmail, Integer excludeId) {
518	        if (normalizedEmail == null) {
519	            return false;
520	        }
521	        for (Owner existing : this.clinicService.findAllOwners()) {
522	            if (excludeId != null && excludeId.equals(existing.getId())) {
523	                continue;
524	            }
525	            String existingEmail = existing.getEmail();
526	            if (existingEmail != null && normalizedEmail.equalsIgnoreCase(existingEmail)) {
527	                return true;
528	            }
529	        }
530	        return false;
531	    }
532	
533	}
